const unplacedTenants = `-- name: UnplacedTenants :many
SELECT DISTINCT tenant_id FROM uma_events WHERE position < 0
`

// The tenants holding events at placeholders, through
// uma_events_placeholders.
func (q *Queries) UnplacedTenants(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, unplacedTenants)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var tenant_id string
		if err := rows.Scan(&tenant_id); err != nil {
			return nil, err
		}
		items = append(items, tenant_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

